svg.script:
/* jsDelivr serves .html as text/plain, so a plain iframe src would show
   source. Fetch the file and hand the markup to the frame instead.
   Override the target with loader.svg?u=<encoded url> */
(function () {
  var DEFAULT = 'https://cdn.jsdelivr.net/gh/NoobVrGT/Mono@main/Mono.html';
  var frame = document.getElementById('monoFrame');
  var boot = [document.getElementById('boot'), document.getElementById('bootText')];

  function target() {
    try {
      var q = new URLSearchParams(window.location.search).get('u');
      return (q || DEFAULT);
    } catch (e) { return DEFAULT; }
  }

  function baseOf(url) {
    return String(url).replace(/[^/]*$/, '');
  }

  /* Relative ./proxy/... paths must resolve against the CDN, not against
     wherever this loader happens to live. */
  function withBase(html, url) {
    var tag = '<base href="' + baseOf(url) + '">';
    if (/<head[^>]*>/i.test(html)) {
      return html.replace(/<head[^>]*>/i, function (m) { return m + tag; });
    }
    return tag + html;
  }

  function hideBoot() {
    boot.forEach(function (el) { if (el) el.style.display = 'none'; });
  }

  function fail(msg) {
    hideBoot();
    frame.srcdoc = '<!doctype html><meta charset="utf-8"><style>' +
      'html,body{margin:0;height:100%;background:#090a0f;color:#c9cedb;' +
      'font:14px/1.7 -apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;' +
      'display:flex;align-items:center;justify-content:center;text-align:center}' +
      'p{margin:0 0 10px}small{color:#7d8496;letter-spacing:3px;font-size:11px}' +
      'code{color:#7d8496;font-size:12px}a{color:#9db4ff;text-decoration:none;' +
      'border-bottom:1px solid rgba(157,180,255,.45)}</style>' +
      '<div><small>MONO</small><p>Could not reach the CDN.</p>' +
      '<p><code>' + String(msg) + '</code></p>' +
      '<p><a href="#" id="again">try again</a></p></div>' +
      '<script>document.getElementById("again").onclick=function(e){e.preventDefault();location.reload()}<\/script>';
  }

  var url = target();
  fetch(url, { cache: 'no-store' })
    .then(function (r) {
      if (!r.ok) throw new Error('HTTP ' + r.status);
      return r.text();
    })
    .then(function (html) {
      if (!/<\s*(!doctype|html)/i.test(html)) throw new Error('not an html document');
      frame.addEventListener('load', hideBoot);
      frame.srcdoc = withBase(html, url);
    })
    .catch(function (e) { fail(e && e.message ? e.message : 'unknown error'); });
})();
